<script setup lang="ts">
import { computed,ref,watch,nextTick } from 'vue'
import { useRoute } from 'vue-router'
import { useApp } from '../stores/app'
import { categories } from '../lib/types'
import Icon from '../components/Icon.vue'
const app=useApp(),route=useRoute(),query=ref(''),category=ref(String(route.query.category||'全部')),input=ref<HTMLInputElement>(),covers=ref<Record<string,string>>({}),busy=ref(false),radar=ref('全部')
const saved=computed(()=>route.path==='/bookmarks')
const rows=computed(()=>app.published.filter(p=>(radar.value==='全部'||(radar.value==='GitHub'?p.content_kind==='project'&&p.tags.includes('GitHub'):radar.value==='Hugging Face'?p.content_kind==='project'&&p.tags.includes('Hugging Face'):p.content_kind==='model_update'||p.tags.includes('模型升级')))&&(!saved.value||app.bookmarks.includes(p.id))&&(category.value==='全部'||p.category===category.value)&&`${p.title} ${p.short_summary} ${p.source_name} ${p.tags.join(' ')}`.toLocaleLowerCase().includes(query.value.trim().toLocaleLowerCase())))
watch(()=>route.query,async()=>{if(route.query.category)category.value=String(route.query.category);if(route.query.focus){await nextTick();input.value?.focus()}},{immediate:true})
let gen=0
watch(rows,async items=>{const n=++gen;const results=await Promise.allSettled(items.map(async p=>[p.id,await app.imageFor(p)]));if(n!==gen)return;covers.value=Object.fromEntries(results.filter(r=>r.status==='fulfilled').map(r=>r.value))},{immediate:true})
async function followKeyword(){if(!query.value.trim())return;try{await app.toggleFollow('keyword',query.value.trim())}catch{}}
const followingKeyword=computed(()=>app.follows.some(f=>f.kind==='keyword'&&f.value===query.value.trim()))
async function toggle(id:string){try{await app.toggleInteraction('bookmarks',id)}catch{}}
async function follow(){if(category.value==='全部')return;busy.value=true;try{await app.toggleFollow('category',category.value)}catch{}finally{busy.value=false}}
const following=computed(()=>app.follows.some(f=>f.kind==='category'&&f.value===category.value))
</script>
<template><div class="page library-page"><div class="page-heading"><div><div class="eyebrow">{{saved?'YOUR PERSONAL COLLECTION':'A WORLD TO DISCOVER'}}</div><h1>{{saved?'把好内容，留给以后。':'好奇，不止一个方向。'}}<span class="orange">↗</span></h1><p>{{saved?`这里收好了你的 ${app.bookmarks.length} 条灵感。`:'搜索新闻、探索主题，建立你的信息视野。'}}</p></div><Icon :name="saved?'Bookmark':'Compass'" :size="40" class="page-heading-icon"/></div><div v-if="!saved" class="radar-tabs"><span><Icon name="Zap" :size="14"/>AI 雷达</span><button v-for="r in ['全部','GitHub','Hugging Face','模型升级']" :key="r" :class="{active:radar===r}" @click="radar=r">{{r}}</button></div><div class="library-search"><Icon name="Search" :size="21"/><input ref="input" v-model="query" maxlength="120" aria-label="搜索新闻" placeholder="输入标题、关键词或来源…"/><button v-if="query" class="icon-btn" aria-label="清空搜索" @click="query=''"><Icon name="X" :size="17"/></button><kbd>ENTER YOUR CURIOSITY</kbd></div><div class="library-filters"><div><button v-for="c in ['全部',...categories]" :key="c" :class="['filter-chip',{active:category===c}]" @click="category=c">{{c}}</button></div><button v-if="!saved&&category!=='全部'" class="btn outline small" :disabled="busy" @click="follow"><Icon :name="following?'Check':'Plus'" :size="14"/>{{following?'已关注分类':'关注分类'}}</button><span v-else class="result-count">{{rows.length}} 条内容</span></div><button v-if="!saved&&query.trim()" class="keyword-follow btn outline small" @click="followKeyword"><Icon :name="followingKeyword?'Check':'Plus'" :size="14"/>{{followingKeyword?'已关注关键词':'关注关键词'}} · {{query.trim()}}</button><div v-if="rows.length" class="news-grid"><article v-for="p in rows" :key="p.id" class="news-tile"><RouterLink :to="`/post/${p.id}`" class="tile-image"><img v-if="covers[p.id]" :src="covers[p.id]" :alt="p.image_attribution" loading="lazy"/><span v-else class="tile-placeholder"><Icon name="Layers3" :size="50"/></span><span class="category-tag">{{p.category}}</span><span class="tile-arrow"><Icon name="ArrowUpRight"/></span></RouterLink><div class="tile-body"><small>{{p.origin==='demo'?'演示内容':p.source_name}}<span> · </span>{{p.tags[0]}}</small><RouterLink :to="`/post/${p.id}`"><h2>{{p.title}}</h2></RouterLink><p>{{p.short_summary}}</p><footer><span>{{p.origin==='demo'?'CONCEPT STORY':'PRIVATE EDITION'}}</span><button class="icon-btn" :class="{orange:app.bookmarks.includes(p.id)}" :aria-label="app.bookmarks.includes(p.id)?'取消收藏':'收藏新闻'" @click="toggle(p.id)"><Icon name="Bookmark" :size="18"/></button></footer></div></article></div><div v-else class="empty-state"><Icon :name="saved?'Bookmark':'Search'" :size="42"/><h2>{{saved?'为下一次灵感，留一个位置':'暂时没有找到相关内容'}}</h2><p>{{saved?'阅读时点击收藏，喜欢的内容就会出现在这里。':'试试其他关键词，或切换分类。'}}</p><RouterLink v-if="saved" to="/" class="btn primary">去读今日推荐<Icon name="ArrowRight" :size="17"/></RouterLink></div></div></template>
